mapper.select:
SELECT doc_no docNo, doc_title docTitle, doc_content docContent, status, createdate
FROM document
WHERE emp_id = (
    SELECT emp_id FROM emp WHERE emp_id = #{empId}
)
ORDER BY createdate DESC

SELECT doc_no docNo, doc_title docTitle, doc_content docContent, status, createdate
FROM document
WHERE emp_id IN (
    SELECT emp_id
    FROM emp
    WHERE dept = (
        SELECT dept FROM emp WHERE emp_id = #{empId}
    )
)
ORDER BY createdate DESC

SELECT doc_no docNo, emp_id empId, doc_title docTitle, doc_content docContent, status, createdate
FROM document
WHERE doc_no = #{docNo}
